#!/usr/bin/env python3
"""One-off generator of nontarget_cal/data/rig_design.yaml (provenance only; not used at run time).

Contents
  rgb.<cam>.design_R_lidar_cam_euler_ZYX_deg : the board rig's rotation rounded to the nearest 10 deg
      per Euler angle (exactly what lidar_odo run_ba.py --init nominal did: "design angles only")
  rgb.<cam>.seed_intr_kb : the team's post-lens-adjustment KB intrinsics (online/seed_camera_*.json)
  rgb.<cam>.reference_T_lidar_cam : the validated 2026-09-24 targetless product (lidar_odo/final),
      used only by the geometric camera-name identification (relative rotations, baseline signs)
  thermal.<cam>: design rotation (thermal_online result rounded to 10 deg), design centre (rounded to
      5 cm), nominal lens and timing of the FLIR A70 (thermal zero-shot start)
"""
import json
from pathlib import Path

import numpy as np
import yaml
from scipy.spatial.transform import Rotation as Rot

RIG = yaml.safe_load(open("/hdd/DM_calib/s2/rig_final.yaml"))
out = {"schema": "nontarget_cal/rig_design/1",
       "note": "generated by tools/make_rig_design.py; T_a_b maps b -> a; os_lidar x points BACKWARD",
       "rgb": {}, "thermal": {}}
for k, v in RIG["cameras"].items():
    c = f"camera_{k}"
    Tlc = np.linalg.inv(np.array(v["T_cam_lidar"], float))
    e = Rot.from_matrix(Tlc[:3, :3]).as_euler("ZYX", degrees=True)
    intr = json.loads(Path(f"/hdd/DM_calib/online/seed_{c}.json").read_text())["intr"]
    fin = json.loads(Path(f"/hdd/DM_calib/lidar_odo/final/{c}.json").read_text())
    out["rgb"][c] = {"design_R_lidar_cam_euler_ZYX_deg": [float(x) for x in np.round(e / 10) * 10],
                     "seed_intr_kb": [float(x) for x in intr],
                     "reference_T_lidar_cam": np.round(np.array(fin["T_lidar_cam"]), 7).tolist()}
th = yaml.safe_load(open("/hdd/DM_calib/thermal_online/thermal_online_calib.yaml"))["cameras"]
for c, v in th.items():
    Tlc = np.linalg.inv(np.array(v["T_cam_lidar"], float))
    e = Rot.from_matrix(Tlc[:3, :3]).as_euler("ZYX", degrees=True)
    out["thermal"][c] = {"design_R_lidar_cam_euler_ZYX_deg": [float(x) for x in np.round(e / 10) * 10],
                         "design_centre_lidar_m": [round(float(x), 3) for x in np.round(Tlc[:3, 3] / 0.05) * 0.05],
                         "nominal_intr_pinhole": [680.0, 680.0, 320.0, 240.0, 0.0, 0.0],
                         "nominal_time_offset_s": -0.100, "nominal_row_readout_s": -0.025,
                         "image_size": [640, 480]}
p = Path(__file__).resolve().parent.parent / "nontarget_cal/data/rig_design.yaml"
p.write_text(yaml.safe_dump(out, sort_keys=False, width=140))
print(p)
